// Real-shell checks for Bash, Zsh, POSIX sh and Dash. These are separate from
// the byte-parity cases in shell_posix_oracle.rs: each test first checks that
// the Rust command line is byte-identical to the pinned Ruby command line, then
// runs it through the real shell found on PATH and checks what the child got.
//
// A shell missing from PATH is reported on stderr as UNVERIFIED, never as a
// pass. With UKIRYU_REQUIRE_SHELL_TESTS=1 a missing shell fails the test on
// Linux, where CI provisions bash, dash, zsh and sh. These shells do not apply
// on Windows, so the checks are reported as not applicable there.

use serde_json::Value;
use std::path::Path;
use std::process::{Command, Output};
use ukiryu::shell::posix::{Bash, Dash, Sh, Zsh};
use ukiryu::shell::ShellFormatting;

fn oracle() -> Value {
    serde_json::from_str(EXEC_ORACLE_JSON).expect("exec oracle JSON")
}

fn text(value: &Value) -> &str {
    value.as_str().expect("oracle string")
}

fn case<'a>(document: &'a Value, shell: &str) -> &'a Value {
    document["cases"]
        .as_array()
        .expect("exec oracle cases")
        .iter()
        .find(|case| case["shell"] == shell)
        .unwrap_or_else(|| panic!("no exec oracle case for {shell}"))
}

fn formatter(shell: &str) -> &'static dyn ShellFormatting {
    match shell {
        "bash" => &Bash,
        "zsh" => &Zsh,
        "sh" => &Sh,
        "dash" => &Dash,
        other => panic!("unknown shell {other}"),
    }
}

fn require_all() -> bool {
    cfg!(target_os = "linux") && std::env::var("UKIRYU_REQUIRE_SHELL_TESTS").as_deref() == Ok("1")
}

/// Returns false (after reporting) when the shell is not applicable or not on PATH.
fn available(shell: &str) -> bool {
    if !cfg!(unix) {
        eprintln!("UNVERIFIED: {shell} checks do not apply on this platform; not passed");
        return false;
    }
    let found = Command::new(shell)
        .args(["-c", "exit 0"])
        .status()
        .map(|status| status.success())
        .unwrap_or(false);
    if !found {
        assert!(
            !require_all(),
            "{shell} is not on PATH but UKIRYU_REQUIRE_SHELL_TESTS=1"
        );
        eprintln!("UNVERIFIED: {shell} is not on PATH; real-shell check skipped, not passed");
    }
    found
}

fn run(shell: &str, line: &str, env: &[(&str, &str)], cwd: Option<&Path>) -> Output {
    let mut command = Command::new(shell);
    command.args(["-c", line]).env("HOME", "/expanded-home");
    for (name, value) in env {
        command.env(name, value);
    }
    if let Some(dir) = cwd {
        command.current_dir(dir);
    }
    let output = command.output().expect("spawn shell");
    assert!(
        output.status.success(),
        "{shell} failed for {line:?}: {output:?}"
    );
    output
}

fn nul_joined<S: AsRef<str>>(values: &[S]) -> Vec<u8> {
    let mut bytes = Vec::new();
    for value in values {
        bytes.extend_from_slice(value.as_ref().as_bytes());
        bytes.push(0);
    }
    bytes
}

/// Every argument passed through `join` reaches the child unchanged.
fn check_join(shell: &str) {
    let document = oracle();
    let arguments: Vec<String> = document["args"]
        .as_array()
        .expect("exec args")
        .iter()
        .map(|value| text(value).to_owned())
        .collect();
    let mut printf_arguments = vec!["%s\\0".to_owned()];
    printf_arguments.extend(arguments.iter().cloned());
    let line = formatter(shell).join("printf", &printf_arguments);
    assert_eq!(line, text(&case(&document, shell)["printf_line"]));
    let output = run(shell, &line, &[], None);
    assert_eq!(output.stdout, nul_joined(&arguments), "{shell}: {line:?}");
}

/// `env_var` output is an unquoted `$NAME`. The shell expands it; bash, sh and
/// dash then split the value on spaces, while zsh does not split by default.
/// That splitting is source behavior and is kept, not fixed.
fn check_env_var(shell: &str) {
    let document = oracle();
    let name = text(&document["env_name"]);
    let target = formatter(shell);
    let format_line = target.join("printf", &["%s\\0".to_owned()]);
    let reference = target.env_var(name);
    let oracle_case = case(&document, shell);
    assert_eq!(format_line, text(&oracle_case["printf_format_line"]));
    assert_eq!(reference, text(&oracle_case["env_ref"]));
    let line = format!("{format_line} {reference}");
    let single = run(shell, &line, &[(name, "probe-value")], None);
    assert_eq!(single.stdout, nul_joined(&["probe-value"]), "{shell}");
    let spaced = run(shell, &line, &[(name, "probe value")], None);
    let expected: &[&str] = if shell == "zsh" {
        &["probe value"]
    } else {
        &["probe", "value"]
    };
    assert_eq!(spaced.stdout, nul_joined(expected), "{shell}");
}

/// A `format_path` result passed through `join` names the real file.
fn check_path(shell: &str) {
    let document = oracle();
    let relative = text(&document["path"]);
    let target = formatter(shell);
    let line = target.join("test", &["-f".to_owned(), target.format_path(relative)]);
    assert_eq!(line, text(&case(&document, shell)["path_line"]));
    let root =
        std::env::temp_dir().join(format!("ukiryu-shell-posix-{shell}-{}", std::process::id()));
    let file = root.join(relative);
    std::fs::create_dir_all(file.parent().expect("parent")).expect("create dir");
    std::fs::write(&file, b"x").expect("write file");
    run(shell, &line, &[], Some(&root));
    std::fs::remove_dir_all(&root).expect("clean up");
}

fn check(shell: &str) {
    if available(shell) {
        check_join(shell);
        check_env_var(shell);
        check_path(shell);
        eprintln!("VERIFIED: {shell} real-shell join, env_var and path checks passed");
    }
}

#[test]
fn bash_executes_oracle_command_lines() {
    check("bash");
}

#[test]
fn zsh_executes_oracle_command_lines() {
    check("zsh");
}

#[test]
fn sh_executes_oracle_command_lines() {
    check("sh");
}

#[test]
fn dash_executes_oracle_command_lines() {
    check("dash");
}
